package netsec

import (
	"encoding/hex"
	"errors"
	"fmt"
)

// TunnelID identifies one EAP tunnel instance. Tunnel IDs are generated by the
// Authenticator and are never derived from an outer or inner identity.
type TunnelID [16]byte

// String returns the hexadecimal form of the tunnel ID.
func (id TunnelID) String() string {
	return hex.EncodeToString(id[:])
}

// IsZero reports whether id is the zero value.
func (id TunnelID) IsZero() bool {
	return id == TunnelID{}
}

// Port identifies one physical port attachment instance.
//
// Name is stable across reconnects (for example, "eth0"). Instance is fresh for
// every call to Authenticator.AttachPort and is what security checks use, so a
// reconnect can never alias the previous attachment merely because it has the
// same name. Ports must be obtained from Authenticator.AttachPort.
type Port struct {
	name       string
	instance   [16]byte
	generation uint64
}

// Name returns the stable physical port name used for diagnostics and routing.
func (p Port) Name() string {
	return p.name
}

// Instance returns a copy of the unique physical attachment identifier.
func (p Port) Instance() [16]byte {
	return p.instance
}

// InstanceID returns the unique physical attachment identifier as hexadecimal.
func (p Port) InstanceID() string {
	return hex.EncodeToString(p.instance[:])
}

// IsZero reports whether p is the zero value.
func (p Port) IsZero() bool {
	return p == Port{}
}

// String returns a diagnostic representation of the port attachment.
func (p Port) String() string {
	if p.IsZero() {
		return "<zero-port>"
	}
	return fmt.Sprintf("%s/%s", p.name, hex.EncodeToString(p.instance[:8]))
}

// TunnelState describes the progress of a tunnel.
type TunnelState uint8

const (
	// TunnelStateOuterIdentity means only the unauthenticated outer identity
	// has been received.
	TunnelStateOuterIdentity TunnelState = iota + 1
	// TunnelStateTunnelEstablished means the protected tunnel exists and its
	// exporter value has been bound.
	TunnelStateTunnelEstablished
	// TunnelStateInnerAuthenticated means the protected inner method completed
	// successfully and a Grant was issued.
	TunnelStateInnerAuthenticated
	// TunnelStateFailed means inner authentication failed.
	TunnelStateFailed
)

// String returns a human-readable tunnel state.
func (s TunnelState) String() string {
	switch s {
	case TunnelStateOuterIdentity:
		return "outer-identity"
	case TunnelStateTunnelEstablished:
		return "tunnel-established"
	case TunnelStateInnerAuthenticated:
		return "inner-authenticated"
	case TunnelStateFailed:
		return "failed"
	default:
		return "unknown"
	}
}

// Principal is an authorization subject. It is created only from a protected
// inner identity after a Grant has been validated. OuterIdentity is
// intentionally absent from this type.
type Principal struct {
	// Name is the protected inner identity.
	Name string
	// Tunnel is the tunnel that authenticated Name.
	Tunnel TunnelID
	// Port is the physical port attachment on which Name authenticated.
	Port Port
}

// Grant is an unforgeable, session-bound record of protected inner
// authentication success.
//
// Its fields are deliberately unexported. A host passes a Grant back to
// Authenticator.Authorize together with the current physical port and tunnel;
// it must not treat the Grant as a reusable bearer token.
type Grant struct {
	nonce            [16]byte
	tunnel           TunnelID
	port             Port
	innerIdentity    string
	exporterDigest   [32]byte
	transcriptDigest [32]byte
	bindingDigest    [32]byte
}

// TunnelID returns the tunnel to which the grant is bound.
func (g Grant) TunnelID() TunnelID {
	return g.tunnel
}

// Port returns the physical port attachment to which the grant is bound.
func (g Grant) Port() Port {
	return g.port
}

// InnerIdentity returns the protected inner identity.
func (g Grant) InnerIdentity() string {
	return g.innerIdentity
}

// ExporterDigest returns a domain-separated digest of the tunnel exporter.
func (g Grant) ExporterDigest() [32]byte {
	return g.exporterDigest
}

// TranscriptDigest returns the digest of the protected inner EAP exchange.
func (g Grant) TranscriptDigest() [32]byte {
	return g.transcriptDigest
}

// BindingDigest returns the MAC that binds the exporter, exchange digest,
// physical port instance, tunnel, and inner identity together.
func (g Grant) BindingDigest() [32]byte {
	return g.bindingDigest
}

// Errors returned by this package. Use errors.Is to test them.
var (
	ErrInvalidPortName       = errors.New("netsec: physical port name is required")
	ErrPortNotAttached       = errors.New("netsec: physical port instance is not attached")
	ErrStalePort             = errors.New("netsec: physical port instance has been replaced")
	ErrTunnelNotFound        = errors.New("netsec: tunnel not found")
	ErrTunnelState           = errors.New("netsec: invalid tunnel state")
	ErrTunnelCompleted       = errors.New("netsec: tunnel already completed")
	ErrExporterRequired      = errors.New("netsec: tunnel exporter is required")
	ErrEmptyExchangePacket   = errors.New("netsec: inner exchange packet is empty")
	ErrExchangePacketTooBig  = errors.New("netsec: inner exchange packet is too large")
	ErrExchangeRequired      = errors.New("netsec: protected inner exchange is required")
	ErrInnerIdentityRequired = errors.New("netsec: protected inner identity is required")
	ErrInnerAuthFailed       = errors.New("netsec: protected inner authentication failed")
	ErrGrantInvalid          = errors.New("netsec: grant is invalid or was not issued by this authenticator")
	ErrBindingMismatch       = errors.New("netsec: grant binding does not match the current session")
	ErrSessionMismatch       = errors.New("netsec: grant belongs to a different tunnel")
)
